    Q("itv4s155", "itv-blob", "Was ist eine Lifecycle-Regel im Prinzip?", "Eine Wenn-dann-Anweisung: Wenn Daten lange nicht geändert wurden, dann verschieben oder löschen", ["Ein SAS-Token", "Ein Failover-Plan", "Eine Firewall-Regel"], ""),
    Q("itv4s156", "itv-blob", "Wie hilft Lifecycle bei der DSGVO?", "Darf man Daten nicht länger als z. B. fünf Jahre aufbewahren, werden sie ab dem ersten Tag danach automatisch gelöscht", ["Sie verschlüsselt die Daten doppelt", "Sie verschiebt Daten in die USA", "Gar nicht"], ""),
    Q("itv4s157", "itv-blob", "Wie oft laufen Lifecycle-Regeln?", "Einmal täglich – Änderungen können bis zu 24 Stunden oder länger brauchen", ["Jede Sekunde", "Einmal pro Jahr", "Nur bei einem Failover"], "Definieren kann man sie im Portal oder in JSON."),
    Q("itv4s158", "itv-blob", "Welche zwei Pricing-Modelle unterscheidet der Vortrag?", "Verbrauchsabhängig (Standard) und provisioniert (Premium und Managed Disks)", ["Pauschal und kostenlos", "Pro Benutzer und pro Region", "Nur nach Anzahl der Container"], ""),
    Q("itv4s159", "itv-blob", "Wobei muss man laut Vortrag beim Pricing zusätzlich aufpassen?", "Bei den Kosten für Tier-Wechsel von Hot nach Cool und umgekehrt", ["Beim Namen des Accounts", "Bei der Anzahl der Endpoints", "Beim Partition Key"], ""),
    Q("itv4s160", "itv-blob", "Was zeigt der Rechner auf Moodle, wenn man wenig zugreift?", "Cold landet schon in der Region von Hot – bei viel Zugriff werden die kalten Tiers immer teurer", ["Archive ist immer am teuersten", "Hot ist immer am billigsten", "Alle Tiers kosten gleich"], "Nur fürs Gefühl, nicht für echte Kosten."),
    Q("itv4s161", "itv-blob", "Womit macht man echte Kostenschätzungen?", "Mit dem Azure Pricing Calculator", ["Mit dem Moodle-Rechner", "Mit AzCopy", "Mit dem Storage Explorer"], "Für Storage und alle anderen Dienste."),
    Q("itv4s162", "itv-blob", "Was kann Object Replication zusätzlich zur Geo-Replikation?", "Feingranular festlegen, wohin Blobs repliziert werden – auch in andere Regionen als die Paired Region", ["Daten synchron in drei Zonen schreiben", "Disks geo-redundant machen", "Queues replizieren"], "Man kann auch erst analysieren und nur die Ergebnisse replizieren."),
    TF("itv4s163", "itv-blob", "Ein Block Blob ist trotz des Namens Object-Storage.", true, ""),
    TF("itv4s164", "itv-blob", "Die Daten im Archive Tier sind verloren, bis Microsoft sie wiederherstellt.", false, "Sie sind nicht weg, nur nicht sofort da – man muss rehydrieren."),
    TF("itv4s165", "itv-blob", "Ob 3,6 TB in wenigen großen Videos oder in vielen kleinen Textdateien liegen, macht bei den Kosten einen großen Unterschied.", true, ""),

    /* 6 · Files, Queue, Table, Disks */
    Q("itv4s170", "itv-svc", "Was bedeutet „Lift and Shift“?", "Etwas von on-premises unverändert in die Cloud heben, ohne auf Cloud-Dienste umzubauen", ["Daten in einen kälteren Tier schieben", "Einen Failover auslösen", "Daten per Data Box schicken"], "Der Fileserver im Keller wird eins zu eins zum Fileserver in der Cloud."),
    Q("itv4s171", "itv-svc", "Welche Protokolle unterstützt Azure Files?", "SMB und NFS – NFS nur bei Premium File Shares", ["Nur HTTP", "Fibre Channel und iSCSI", "SMTP"], ""),
    Q("itv4s172", "itv-svc", "Wann nimmt man Azure Files statt Blob Storage?", "Wenn man eine Verzeichnis-Hierarchie braucht und bestimmte Verzeichnisse für bestimmte Leute sperren will", ["Für Videos auf der Website", "Für Logdateien", "Für VM-Disks"], ""),
    Q("itv4s173", "itv-svc", "Warum gehört ein Video auf der Webseite in Blob Storage?", "Niemand muss eine Hierarchie durchsuchen oder braucht Schreibrechte – ein Klick auf den Link genügt", ["Weil Azure Files keine Videos speichert", "Weil Blob immer billiger als alles ist", "Weil Blob SMB spricht"], ""),
    Q("itv4s174", "itv-svc", "Was ermöglicht Azure File Sync?", "Dass verschiedene Standorte dieselben Daten haben, weil Azure sie über den File-Share synchronisiert", ["Dass Blobs in Archive gehen", "Dass VMs in eine andere Region repliziert werden", "Dass Queues Nachrichten pushen"], ""),
    Q("itv4s175", "itv-svc", "Was legt man für File Sync in Azure an?", "Einen Storage Sync Service", ["Eine Queue", "Eine Data Box", "Einen Partition Key"], ""),
    Q("itv4s176", "itv-svc", "Worauf installiert man den File Sync Agent?", "Auf einem oder mehreren Windows Servern", ["Auf jedem Smartphone", "Auf dem Storage Account selbst", "Auf einem Linux-NAS"], "Die Server registriert man mit Subscription, Resource Group und Sync Service."),
    Q("itv4s177", "itv-svc", "Warum klappt das Einbinden eines File-Shares unter Windows oft nicht?", "Port 445 muss offen sein, und den blockieren viele Internetanbieter und Firmennetze", ["Weil Windows kein SMB kann", "Weil man einen Account Key braucht", "Weil der Share zu groß ist"], "Dann geht es nur über VPN oder File Sync."),
    Q("itv4s178", "itv-svc", "Was unterscheidet einen Snapshot von einer Version?", "Einen Snapshot löst man zu einem Zeitpunkt aus (selbst oder per Zeitplan), eine Version entsteht bei jedem Schreibvorgang", ["Nichts", "Versionen löst man manuell aus", "Snapshots gibt es nur bei Blobs"], ""),
    Q("itv4s179", "itv-svc", "Womit arbeitet man bei File-Shares statt Versionierung?", "Mit Snapshots", ["Mit Append Blobs", "Mit Smart Tier", "Mit Partition Keys"], "Versionierung gibt es bei Blob Storage."),
    Q("itv4s180", "itv-svc", "Was legt die Web-App im Thumbnail-Beispiel in die Queue?", "Die HTTPS-URL des großen Fotos im Blob-Container", ["Das ganze Foto", "Das fertige Thumbnail", "Den Account Key"], "„Schau, da ist das große Foto.“"),
    Q("itv4s181", "itv-svc", "Was macht der Worker-Prozess?", "Er holt sich die URL, lädt das Foto, erzeugt das Thumbnail und speichert es in einem anderen Container", ["Er löscht die Queue", "Er pusht Nachrichten an die Web-App", "Er rehydriert Archive-Blobs"], ""),
    Q("itv4s182", "itv-svc", "Wer fragt wen bei Queue Storage?", "Der Worker fragt die Queue ab – eine Storage Queue pusht nichts", ["Die Queue pusht dem Worker die Nachricht", "Die Queue ruft die Web-App an", "Niemand, alles läuft per E-Mail"], "Das war eine Korrektur im Skript."),
    Q("itv4s183", "itv-svc", "Wie bekommt man trotzdem ein Verhalten wie ein Trigger?", "Mit einer Azure Function mit Queue-Trigger, die das Abfragen übernimmt und den Code aufruft", ["Mit einem Resource Lock", "Mit einer SAS", "Mit dem Archive Tier"], "Vergleichbar mit einem Interrupt."),
    Q("itv4s184", "itv-svc", "Welcher Dienst ist für Enterprise-Messaging die bessere Alternative zu Queue Storage?", "Service Bus", ["Table Storage", "Azure Files", "Data Box"], "Event Grid für Ereignisse, Event Hubs für Streaming (Kafka-kompatibel)."),
    Q("itv4s185", "itv-svc", "Welcher Azure-Dienst ist Kafka-kompatibel für Streaming gedacht?", "Event Hubs", ["Event Grid", "Queue Storage", "Table Storage"], ""),
    Q("itv4s186", "itv-svc", "Was ist Table Storage?", "Ein NoSQL-Speicher für Key-Value-Paare", ["Eine relationale SQL-Datenbank", "Ein File-Share", "Ein Disk-Typ"], ""),
    Q("itv4s187", "itv-svc", "Welches Beispiel nennt der Vortrag für Table Storage?", "Die Einstellungen eines Benutzers, etwa dunkler Hintergrund oder andere Schrift", ["4K-Videos", "VM-Betriebssysteme", "Logdateien zum Anhängen"], "Vorteil: billiger als eine verwaltete SQL-Datenbank."),
    Q("itv4s188", "itv-svc", "Was braucht jeder Eintrag in Table Storage?", "Einen Partition Key und einen Row Key, die gemeinsam eindeutig sind", ["Eine LUN", "Ein SAS-Token", "Eine Version"], "Dazu kommt automatisch ein Timestamp."),
    Q("itv4s189", "itv-svc", "Wie viele Properties stehen in einer Table-Entity frei zur Verfügung?", "252 von 255", ["255 von 255", "3", "64"], "Partition Key, Row Key und Timestamp sind belegt."),
    Q("itv4s190", "itv-svc", "Was gilt im Bookstore-Beispiel?", "Man muss nicht für jedes Buch dieselben Felder befüllen – man hinterlegt, was man hat", ["Jedes Buch braucht exakt dieselben Spalten", "Nur ISBN ist erlaubt", "Bücher müssen in einen Container"], ""),
    Q("itv4s191", "itv-svc", "Partition Key = Stadt, Row Key = Name. Wo landen alle Personen aus Rom?", "In einer gemeinsamen Partition", ["Jede in einer eigenen Region", "In einer Queue", "Im Archive Tier"], "Partitionen sieht man nicht; sie sorgen dafür, dass Daten schnell gefunden werden."),
    Q("itv4s192", "itv-svc", "Welche Redundanz gibt es für Managed Disks?", "LRS oder ZRS – nicht geo-redundant", ["Nur RA-GZRS", "GRS als Standard", "Gar keine"], ""),
    Q("itv4s193", "itv-svc", "Was ist von der Replikation der Managed Disks getrennt und sollte man trotzdem machen?", "Ein Backup – mit Azure Backup oder Azure Site Recovery", ["Ein Failover pro Woche", "Ein Tier-Wechsel nach Archive", "Ein CNAME-Eintrag"], ""),
    Q("itv4s194", "itv-svc", "Was macht Azure Site Recovery?", "Es repliziert ganze VMs in eine andere Region, damit man sie dort im Notfall starten kann", ["Es synchronisiert File-Shares zwischen Standorten", "Es rehydriert Blobs", "Es rotiert Account Keys"], ""),
    Q("itv4s195", "itv-svc", "Welche Abstufung der Disk-Typen nennt der Vortrag?", "Von der günstigen HDD über verschiedene SSD-Varianten bis zur Ultra Disk für sehr anspruchsvolle Datenbanken", ["Nur eine einzige Disk-Art", "Hot, Cool, Cold, Archive", "LRS, ZRS, GRS"], ""),
    TF("itv4s196", "itv-svc", "Queue Storage ist laut Vortrag die simpelste Messaging-Lösung in Azure.", true, ""),
    TF("itv4s197", "itv-svc", "Mit File Sync ist eine in Graz hochgeladene Datei über Azure bald auch an den anderen Standorten verfügbar.", true, ""),
    TF("itv4s198", "itv-svc", "Managed Disks können geo-redundant über Regionsgrenzen replizieren.", false, "Nur LRS oder ZRS."),

    /* 7 · Security & Netzwerk */
    Q("itv4s200", "itv-sec", "Wie wird der Speicher eines Storage Accounts verschlüsselt?", "Immer automatisch mit AES-256 – nicht abschaltbar, ohne Code-Änderung", ["Nur wenn man es aktiviert", "Gar nicht", "Nur bei Premium"], ""),
    Q("itv4s201", "itv-sec", "Welcher Zugriffsweg ist laut Vortrag „am gescheitesten“?", "Entra ID mit RBAC", ["Anonymer Zugriff", "Account Keys", "Eine SAS per E-Mail"], ""),
    Q("itv4s202", "itv-sec", "Wann ist anonymer Zugriff laut Vortrag vertretbar?", "Wenn man die Daten ohnehin mit der ganzen Welt teilt", ["Für Rechnungen", "Für Kundendaten", "Nie, er existiert nicht"], ""),
    Q("itv4s203", "itv-sec", "Was erlauben Owner und Contributor beim Storage Account?", "Die Verwaltung des Accounts – aber nicht automatisch das Lesen der Daten über Entra ID", ["Automatisch Lesen und Schreiben aller Blobs", "Gar nichts", "Nur das Lesen der Daten"], "Dafür braucht es Datenrollen."),
    Q("itv4s204", "itv-sec", "Welche Rolle braucht man, um Blob-Daten über Entra ID zu lesen?", "Eine Datenrolle wie Storage Blob Data Reader", ["Reader auf der Subscription", "Global Administrator", "Keine, Owner reicht"], "Zum Schreiben: Storage Blob Data Contributor."),
    Q("itv4s205", "itv-sec", "Womit vergleicht der Vortrag eine Shared Access Signature?", "Mit einem OneDrive-Freigabelink: für eine gewisse Zeit, lange URL, jeder mit der URL kann sie nutzen", ["Mit einem Resource Lock", "Mit einer LUN", "Mit einem RAID"], ""),
    Q("itv4s206", "itv-sec", "Was legt man im Portal beim Erstellen einer SAS fest?", "Startdatum, Enddatum, Protokoll, Berechtigungen und den Key zum Signieren", ["Nur den Container-Namen", "Die Paired Region", "Den Access Tier"], ""),
    Q("itv4s207", "itv-sec", "Wie lange ist die Signatur einer SAS gültig?", "Nur solange der Key gültig ist, mit dem sie signiert wurde (und bis zum eingestellten Ablauf)", ["Für immer", "Genau 24 Stunden", "Bis zum nächsten Failover"], ""),
    Q("itv4s208", "itv-sec", "Wie viele Access Keys hat ein Storage Account?", "Zwei", ["Einen", "Drei", "Keinen"], "Wer sie hat, kann alle Daten lesen."),
    Q("itv4s209", "itv-sec", "Eine normale SAS ist in falsche Hände geraten. Was hilft, wenn sie an keiner Stored Access Policy hängt?", "Den Key rotieren, mit dem sie erzeugt wurde – dann sind alle damit signierten SAS unbrauchbar", ["Nichts, man muss warten", "Den Tier wechseln", "Den Account umbenennen"], ""),
    Q("itv4s210", "itv-sec", "Was kann man tun, wenn die SAS an einer Stored Access Policy hängt?", "Die Policy ändern oder löschen", ["Die Policy rehydrieren", "Den Container nach Archive schieben", "Nichts"], ""),
    Q("itv4s211", "itv-sec", "Womit wird eine User Delegation SAS signiert?", "Mit Entra-ID-Anmeldedaten statt mit dem Account Key", ["Mit dem Account Key", "Mit einem CNAME", "Gar nicht"], "Sie gilt höchstens sieben Tage und lässt sich gezielter widerrufen."),
    Q("itv4s212", "itv-sec", "Wie lange darf eine User Delegation SAS höchstens gelten?", "Sieben Tage", ["Einen Tag", "Ein Jahr", "Unbegrenzt"], ""),
    Q("itv4s213", "itv-sec", "Wie sollte eine selbst geschriebene Anwendung auf den Storage zugreifen?", "Über einen Service Principal bzw. eine Managed Identity mit RBAC – nicht mit den Keys", ["Mit einem Account Key im Code", "Anonym", "Über Port 445"], ""),
    Q("itv4s214", "itv-sec", "Wo legt man Customer-managed Keys ab?", "In einem Azure Key Vault", ["Im Blob-Container", "In der Queue", "Auf einer USB-Platte"], "Alternativ verwendet man Microsoft-verwaltete Schlüssel."),
    Q("itv4s215", "itv-sec", "Was gilt für die Verschlüsselung von VM-Disks?", "Es gibt Encryption at Host; die ältere Azure Disk Encryption wird im September 2028 eingestellt", ["VM-Disks sind nie verschlüsselt", "Azure Disk Encryption ist der neue Standard ab 2028", "Nur Premium-Disks sind verschlüsselt"], ""),
    Q("itv4s216", "itv-sec", "Welche Firewall-Optionen nennt der Vortrag für einen Storage Account?", "Alle aus dem Internet, nur bestimmte öffentliche IPs oder nur Server aus einem bestimmten VNet/Subnetz", ["Nur alle oder niemand", "Nur nach Benutzername", "Nur nach Dateigröße"], ""),
    Q("itv4s217", "itv-sec", "Was ist ein Private Endpoint?", "Eine private IP-Adresse für den Storage Account – er ist dann nur noch über dieses Netzwerk erreichbar", ["Ein zweiter öffentlicher Endpoint", "Ein Endpoint in der Paired Region", "Ein SAS-Token"], "Von außen geht es dann nur noch über VPN."),
    Q("itv4s218", "itv-sec", "Muss ein Storage Account aus dem Internet erreichbar sein, weil er eine URL hat?", "Nein – er kann auch ein privater Speicher für interne Zwecke sein", ["Ja, immer", "Ja, sonst funktioniert HTTPS nicht", "Nur bei Premium nicht"], ""),
    Q("itv4s219", "itv-sec", "Welches Szenario zeigt die Netzwerk-Simulation zusätzlich?", "Ein bösartiger Mitarbeiter mit Zugriff auf den Webserver kopiert Daten in einen fremden Storage Account", ["Ein Erdbeben in North Europe", "Ein Tier-Wechsel nach Archive", "Ein Blitzschlag ins NAS"], ""),
    Q("itv4s220", "itv-sec", "Was verhindert eine Service Endpoint Policy?", "Dass ein Subnetz andere als die erlaubten Storage Accounts erreicht – also das Abziehen in fremde Accounts", ["Dass jemand den Account löscht", "Dass Daten verschlüsselt werden", "Dass Smart Tier läuft"], ""),
    Q("itv4s221", "itv-sec", "Was ist laut Vortrag beim Netzwerkzugriff vor allem wichtig?", "Zu wissen, dass es das alles gibt – man muss nicht gleich die große Firewall auspacken", ["Immer eine Hardware-Firewall kaufen", "Alles öffentlich lassen", "Nur Account Keys verwenden"], ""),
    TF("itv4s222", "itv-sec", "Die Verschlüsselung des Storage Accounts kann man abschalten, um Kosten zu sparen.", false, ""),
    TF("itv4s223", "itv-sec", "Das SAS-Token ist lang, aber lesbar – man erkennt zum Beispiel das Datum.", true, ""),
    TF("itv4s224", "itv-sec", "Rotiert man einen Key, werden alle damit signierten SAS unbrauchbar.", true, "Das wird bei jedem Zugriff geprüft."),

    /* 8 · Protection, Backup, Tools */
    Q("itv4s230", "itv-prot", "Wie kann man sich Soft Delete vorstellen?", "Wie einen Papierkorb, aus dem man Gelöschtes wiederherstellt", ["Wie ein RAID", "Wie einen Failover", "Wie einen Archive Tier"], ""),
    Q("itv4s231", "itv-prot", "Was ist Point-in-time Restore?", "Eine Funktion, die die Block Blobs eines Containers auf den Stand eines Zeitpunkts zurücksetzt", ["Die Dauer einer Wiederherstellung", "Die RPO", "Ein Backup-Gerät"], "Wie ein „Rückgängig“ für den ganzen Container."),
    Q("itv4s232", "itv-prot", "Wofür steht WORM?", "Write Once, Read Many", ["Write Often, Read Mostly", "Worldwide Object Replication Model", "Write Only, Remove Monthly"], "Einmal schreiben, beliebig oft lesen, nie mehr ändern."),
    Q("itv4s233", "itv-prot", "Wofür ist Immutable Storage laut Vortrag wichtig?", "Für Rechnungen oder Projektdaten, die man vielleicht 30 Jahre aufbewahren muss", ["Für Thumbnails", "Für Cloud-Shell-Dateien", "Für Queue-Nachrichten"], "Es gibt auch spezialisierte Dokumentenmanagementsysteme."),
    Q("itv4s234", "itv-prot", "Was passiert ohne Schutz, wenn jemand die Resource Group mit dem Storage Account löscht?", "Alles ist weg, sofern es kein Backup an anderer Stelle gibt", ["Nichts, Azure verhindert das automatisch", "Die Daten wandern nach Archive", "Die Paired Region übernimmt"], "Schutz: ein Resource Lock."),
    Q("itv4s235", "itv-prot", "Wie lange lässt sich ein gelöschter Storage Account unter Umständen wiederherstellen?", "Innerhalb von 14 Tagen – verlassen sollte man sich darauf aber nicht", ["Für immer", "Nie", "Genau 7 Jahre"], ""),
    Q("itv4s236", "itv-prot", "Was besagt die 3-2-1-Backup-Regel?", "Drei Kopien, auf zwei verschiedenen Medien, eine davon an einem anderen Ort", ["Drei Regionen, zwei Zonen, ein Rack", "Drei Backups pro Tag, zwei pro Nacht, eines am Wochenende", "Drei Accounts, zwei Keys, eine SAS"], ""),
    Q("itv4s237", "itv-prot", "Was kostet jedes Backup laut Vortrag?", "Speicherplatz – egal ob in der Cloud oder anderswo", ["Nichts", "Eine Lizenz pro Benutzer", "Einen Failover"], "Wie oft man sichert, hängt von den Daten ab."),
    Q("itv4s238", "itv-prot", "Was ist die RTO?", "Die Zeit, bis das System nach dem Ausfall wieder läuft – bis das Backup eingespielt ist", ["Die Zeitspanne an verlorenen Daten", "Die Zeit bis zur nächsten Rechnung", "Die Zahl der Kopien"], ""),
    Q("itv4s239", "itv-prot", "Backup um 14 Uhr, Ausfall am nächsten Tag um 13:58 Uhr. Wie viele Daten gehen verloren?", "Knapp 24 Stunden (RPO)", ["2 Minuten", "14 Stunden", "Keine"], ""),
    Q("itv4s240", "itv-prot", "Ein Mitarbeiter löscht versehentlich eine Datei. Was hilft laut Vortrag?", "Der Papierkorb (Soft Delete)", ["Replikation", "Ein Failover", "Smart Tier"], ""),
    Q("itv4s241", "itv-prot", "Ein Skript hat Daten überschrieben. Was hilft?", "Die Versionierung", ["Ein Resource Lock", "Die Replikation", "Ein CNAME"], ""),
    Q("itv4s242", "itv-prot", "Was hilft gegen Ransomware?", "Ein Backup", ["Die Replikation in die Sekundärregion", "Ein geplanter Failover", "Der Hot Tier"], "Replikation hilft gar nicht – die verschlüsselten Daten werden sofort mitrepliziert."),
    Q("itv4s243", "itv-prot", "Was hilft, wenn eine ganze Region ausfällt?", "In die andere Region wechseln", ["Der Papierkorb", "Die Versionierung", "Ein Resource Lock"], "Voraussetzung: Geo-Redundanz."),
    Q("itv4s244", "itv-prot", "Was ist der Azure Storage Explorer?", "Eine eigene App für Mac, Linux und Windows zum Verwalten von Storage Accounts – teils mit mehr als im Portal", ["Ein Webbrowser-Plugin nur für Windows", "Ein Backup-Gerät", "Ein Access Tier"], ""),
    Q("itv4s245", "itv-prot", "Wofür ist AzCopy gedacht?", "Um über die Kommandozeile schnell Daten hin und her zu kopieren", ["Um Accounts grafisch zu verwalten", "Um Partition Keys zu vergeben", "Um VMs zu replizieren"], ""),
    Q("itv4s246", "itv-prot", "Was ist Azure Data Box?", "Ein Gerät, das Microsoft schickt; man befüllt es und schickt es zurück, die Daten werden im Rechenzentrum eingespielt", ["Ein Access Tier für große Daten", "Eine Queue für Bestellungen", "Ein NAS von Synology"], "Beim Import/Export-Service nimmt man eigene Festplatten."),
    Q("itv4s247", "itv-prot", "Wie lange dauern 100 TB über eine 1-Gbit/s-Leitung bei voller Geschwindigkeit?", "Mehr als neun Tage", ["Etwa eine Stunde", "Etwa einen Tag", "Genau 15 Stunden"], ""),
    Q("itv4s248", "itv-prot", "Entscheidungshilfe: Man braucht einen gemeinsamen Ordner per SMB. Was nimmt man?", "Azure Files", ["Managed Disk", "Queue Storage", "Table Storage"], ""),
    Q("itv4s249", "itv-prot", "Entscheidungshilfe: Nachrichten zwischen Anwendungsteilen?", "Queue Storage", ["Azure Files", "Managed Disk", "Archive"], ""),
    Q("itv4s250", "itv-prot", "Entscheidungshilfe: Was nimmt man für „alles andere“ – Dateien und Objekte über HTTPS?", "Blob Storage mit passendem Tier und Lifecycle", ["Table Storage", "Managed Disk", "Azure Files"], "Danach entscheidet man über Redundanz, Zugriff, Netzwerk und Schutzfunktionen."),
    Q("itv4s251", "itv-prot", "Wie übt man laut Vortrag kostenlos mit einem eigenen Storage Account?", "Keine Daten hochladen, keine großen Premium-Disks wählen und alles nach dem Üben wieder löschen", ["Nur Premium-Accounts nehmen", "Alles in RA-GZRS anlegen", "Ein Jahr laufen lassen"], ""),
    TF("itv4s252", "itv-prot", "Replikation schützt zuverlässig vor Ransomware.", false, "Die verschlüsselten Daten werden sofort mitrepliziert."),
    TF("itv4s253", "itv-prot", "RPO und RTO sollte man beide in einem Backup-Plan berücksichtigen.", true, ""),
    TF("itv4s254", "itv-prot", "Einen Storage Account kann man auch mit az-Befehlen der Azure CLI anlegen.", true, "")
